// Chuyển ảnh sang base64 và dựng body gọi Claude Vision
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');
const meta = $input.item.binary.data;
const mimeType = (meta && meta.mimeType) ? meta.mimeType : 'image/jpeg';

const trigger = $('Drive: ảnh phiếu mới').item.json;

const prompt = `Bạn là trợ lý đọc PHIẾU CÂN của nhà máy xay xát gạo Thạnh Hương.
Ảnh là một phiếu cân (có thể là phiếu THU MUA LÚA đầu vào, hoặc phiếu BÁN cám/trấu/gạo đầu ra; có thể của nhà máy hoặc của đối tác như De Heus, CP).
Hãy đọc kỹ và trích xuất thông tin. Chữ IN/số máy in đọc chính xác; với chữ VIẾT TAY hãy cẩn thận và hạ độ tin cậy nếu không chắc.

TRẢ VỀ DUY NHẤT một object JSON (không thêm lời giải thích, không bọc trong markdown) theo đúng cấu trúc:
{
  "ngay": "ngày trên phiếu, định dạng DD/MM/YYYY nếu đọc được",
  "so_phieu": "số phiếu / số chứng từ",
  "nguoi_ban_khach_hang": "tên nhà cung cấp / người bán / khách hàng",
  "loai_hang_lua": "loại hàng hoặc loại lúa (vd: lúa tươi, OM5451, cám gạo, trấu...)",
  "so_xe": "biển số xe",
  "tl_xe_vao": "trọng lượng xe vào / xe có hàng, chỉ lấy số kg",
  "tl_xe_ra": "trọng lượng xe ra / xe không, chỉ lấy số kg",
  "tl_hang": "trọng lượng hàng (tịnh), chỉ lấy số kg",
  "do_am": "độ ẩm % nếu có, ngược lại để rỗng",
  "kieu_can": "NHẬP hay XUẤT nếu xác định được",
  "ghi_chu_chat_luong": "mọi ghi chú về chất lượng, tạp chất, sâu mọt... nếu có",
  "nguoi_can": "tên người cân nếu có",
  "do_tin_cay": "một trong: cao | trung bình | thấp — đánh giá tổng thể độ chắc chắn khi đọc, đặc biệt các ô viết tay/mờ",
  "can_kiem_tra": true hoặc false — đặt true nếu có bất kỳ trường quan trọng nào (số cân, người bán, loại lúa) bạn không chắc,
  "ly_do_kiem_tra": "giải thích ngắn vì sao cần kiểm tra, để rỗng nếu không cần"
}
Nếu một trường không có trên phiếu, để chuỗi rỗng "". Các trường trọng lượng chỉ ghi con số (không kèm 'kg', không dấu phẩy ngăn cách nghìn).`;

return {
  json: {
    fileId: trigger.id,
    fileName: trigger.name,
    body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 1024,
      messages: [
        {
          role: 'user',
          content: [
            { type: 'image', source: { type: 'base64', media_type: mimeType, data: base64 } },
            { type: 'text', text: prompt }
          ]
        }
      ]
    }
  }
};

// Phân tích kết quả Claude trả về + kiểm tra logic số cân
const prep = $('Chuẩn bị yêu cầu Claude').item.json;
const fileId = prep.fileId;
const fileName = prep.fileName;

// Lấy text JSON từ phản hồi Anthropic
let text = '';
try {
  text = $json.content[0].text;
} catch (e) {
  text = '';
}

let clean = (text || '').trim();
clean = clean.replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();

let data = {};
let parseError = '';
try {
  data = JSON.parse(clean);
} catch (e) {
  parseError = 'Không đọc được JSON từ AI';
  data = {};
}

const toNum = (s) => {
  if (s === null || s === undefined || s === '') return null;
  const n = Number(String(s).replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? null : n;
};

const vao = toNum(data.tl_xe_vao);
const ra = toNum(data.tl_xe_ra);
const hang = toNum(data.tl_hang);

// Kiểm tra logic: |vào - ra| phải xấp xỉ trọng lượng hàng
let mathOk = true;
let mathNote = '';
if (vao !== null && ra !== null && hang !== null) {
  const diff = Math.abs(Math.abs(vao - ra) - hang);
  const tol = Math.max(20, hang * 0.01); // sai số cho phép 20kg hoặc 1%
  if (diff > tol) {
    mathOk = false;
    mathNote = `Lệch cân: |${vao}-${ra}| = ${Math.abs(vao - ra)} khác TL hàng ${hang}`;
  }
}

const conf = String(data.do_tin_cay || '').toLowerCase();
const lowConf = conf.includes('thấp') || conf.includes('thap') || conf === 'low';
const aiFlag = data.can_kiem_tra === true || data.can_kiem_tra === 'true';

const needsReview = !!(parseError || lowConf || !mathOk || aiFlag);

let reasons = [];
if (parseError) reasons.push(parseError);
if (lowConf) reasons.push('AI báo độ tin cậy thấp');
if (!mathOk) reasons.push(mathNote);
if (aiFlag && data.ly_do_kiem_tra) reasons.push(data.ly_do_kiem_tra);
else if (aiFlag) reasons.push('AI đánh dấu cần kiểm tra');

return {
  json: {
    'Thời gian xử lý': new Date().toISOString(),
    'Tên file': fileName || '',
    'Link ảnh': fileId ? `https://drive.google.com/file/d/${fileId}/view` : '',
    'Ngày phiếu': data.ngay || '',
    'Số phiếu': data.so_phieu || '',
    'Người bán / Khách hàng': data.nguoi_ban_khach_hang || '',
    'Loại hàng / lúa': data.loai_hang_lua || '',
    'Số xe': data.so_xe || '',
    'TL xe vào (kg)': vao !== null ? vao : '',
    'TL xe ra (kg)': ra !== null ? ra : '',
    'TL hàng (kg)': hang !== null ? hang : '',
    'Độ ẩm (%)': data.do_am || '',
    'Kiểu cân': data.kieu_can || '',
    'Ghi chú chất lượng': data.ghi_chu_chat_luong || '',
    'Người cân': data.nguoi_can || '',
    'Độ tin cậy': data.do_tin_cay || '',
    'Cần kiểm tra': needsReview ? 'CÓ' : 'Không',
    'Lý do kiểm tra': reasons.join('; ')
  }
};
